package main

import (
	"fmt"
	"go/format"
	"strings"
	"unicode"
)

// goGen makes Go/wire's generated files: a type per definition, and the methods.
type goGen struct {
	doc   *Document
	out   strings.Builder
	named map[string]bool // every Go type name taken, definitions and inline types
	queue []func()        // inline types, written after the type that holds them
}

func goTypes(doc *Document) (string, error) {
	g := &goGen{doc: doc, named: map[string]bool{}}
	for _, name := range doc.Names {
		g.named[name] = true
	}
	for _, name := range doc.Names {
		s := doc.Definitions[name]
		if s.GoType != "" {
			continue // written by hand in Go/wire
		}
		g.definition(name, s)
		for len(g.queue) > 0 {
			next := g.queue[0]
			g.queue = g.queue[1:]
			next()
		}
	}
	return gofmt(file(g.out.String()))
}

// file puts the header and the package clause on a body, and the import it uses.
func file(body string) string {
	src := header + "\npackage wire\n"
	if strings.Contains(body, "json.") {
		src += "\nimport \"encoding/json\"\n"
	}
	return src + body
}

const header = "// Code generated by scripts/wire.sh gen (Go/cmd/wiregen) from Packages/Wire. DO NOT EDIT.\n"

func gofmt(src string) (string, error) {
	b, err := format.Source([]byte(src))
	if err != nil {
		return src, fmt.Errorf("gofmt: %w", err)
	}
	return string(b), nil
}

func (g *goGen) comment(text, indent string) {
	if text == "" {
		return
	}
	for _, line := range strings.Split(text, "\n") {
		g.out.WriteString(indent + "// " + line + "\n")
	}
}

// apart puts a blank line before each field but the first: gofmt aligns a run of fields,
// so a field with a longer name would change every line of its struct, and two features
// that each add one would conflict (#2020).
func (g *goGen) apart(i int) {
	if i > 0 {
		g.out.WriteString("\n")
	}
}

// definition writes a named type for a definition or an inline schema.
func (g *goGen) definition(name string, s *Schema) {
	g.out.WriteString("\n")
	g.comment(s.Description, "")
	if names, payloads, ok := s.Cases(); ok {
		g.cases(name, s, names, payloads)
		return
	}
	if tag, ok := s.Tagged(); ok {
		g.tagged(name, s, tag)
		return
	}
	if s.Is("object") && (len(s.Properties) > 0 || s.More == nil) {
		g.object(name, s)
		return
	}
	if s.Is("string") && s.Enum != nil {
		g.enum(name, s)
		return
	}
	t := g.typeOf(s, name)
	if t == "JSONValue" {
		// An alias, so it keeps json.RawMessage's own MarshalJSON: a type made from it
		// would be written as base64.
		fmt.Fprintf(&g.out, "type %s = %s\n", name, t)
		return
	}
	fmt.Fprintf(&g.out, "type %s %s\n", name, t)
}

func (g *goGen) object(name string, s *Schema) {
	fmt.Fprintf(&g.out, "type %s struct {\n", name)
	seen := map[string]bool{}
	var defaults []string
	for i, p := range s.Properties {
		g.apart(i)
		field := goName(p.Name)
		if seen[field] {
			panic(fmt.Sprintf("%s: two properties are both %s in Go", name, field))
		}
		seen[field] = true
		g.comment(p.Schema.Description, "\t")
		typ := g.field(name+field, p.Schema, s.IsRequired(p.Name))
		tag := p.Name
		if !s.IsRequired(p.Name) {
			tag += ",omitzero"
		}
		fmt.Fprintf(&g.out, "\t%s %s `json:%q`\n", field, typ, tag)
		if p.Schema.HasDefault && !strings.HasPrefix(typ, "*") {
			defaults = append(defaults, fmt.Sprintf("%s: %#v", field, p.Schema.Default))
		}
	}
	g.out.WriteString("}\n")
	if len(defaults) > 0 {
		fmt.Fprintf(&g.out, `
// UnmarshalJSON reads a field that is missing as its default.
func (v *%[1]s) UnmarshalJSON(b []byte) error {
	type plain %[1]s
	p := plain{%[2]s}
	if err := json.Unmarshal(b, &p); err != nil {
		return err
	}
	*v = %[1]s(p)
	return nil
}
`, name, strings.Join(defaults, ", "))
	}
}

// field is a property's Go type: a pointer when it may be left out (or be null) and its
// zero value is not already "absent".
func (g *goGen) field(hint string, s *Schema, required bool) string {
	if inner, ok := s.Nullable(); ok {
		t := g.typeOf(inner, hint)
		if g.nilable(t) {
			return t
		}
		return "*" + t
	}
	t := g.typeOf(s, hint)
	if required || g.nilable(t) {
		return t
	}
	return "*" + t
}

// nilable says whether a Go type's zero value is nil, so that it can say "absent" itself.
func (g *goGen) nilable(t string) bool {
	if strings.HasPrefix(t, "[]") || strings.HasPrefix(t, "map[") || strings.HasPrefix(t, "*") {
		return true
	}
	if s, ok := g.doc.Definitions[t]; ok {
		switch s.GoType {
		case "Data", "JSONValue":
			return true
		case "":
			return s.Is("array") || (s.Is("object") && len(s.Properties) == 0 && s.More != nil && s.More.Not == nil)
		}
	}
	return t == "JSONValue" || t == "Data"
}

func (g *goGen) enum(name string, s *Schema) {
	fmt.Fprintf(&g.out, "type %s string\n\n", name)
	var values []string
	seen := map[string]bool{}
	for _, v := range s.Enum {
		str := v.(string)
		c := name + goName(str)
		if seen[c] {
			panic(fmt.Sprintf("%s: two values are both %s in Go", name, c))
		}
		seen[c] = true
		values = append(values, c)
		// One declaration each, not a block that gofmt aligns (#2020).
		fmt.Fprintf(&g.out, "const %s %s = %q\n", c, name, str)
	}
	if s.Fallback != "" {
		fmt.Fprintf(&g.out, `
// UnmarshalJSON reads a value this build does not know as %[3]q.
func (v *%[1]s) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return err
	}
	switch %[1]s(s) {
	case %[2]s:
		*v = %[1]s(s)
	default:
		*v = %[1]s%[4]s
	}
	return nil
}
`, name, strings.Join(values, ",\n\t\t"), s.Fallback, goName(s.Fallback))
	}
}

// cases writes a Swift enum with associated values: one pointer per case, set for the one
// the value is.
func (g *goGen) cases(name string, s *Schema, names []string, payloads []*Schema) {
	fmt.Fprintf(&g.out, "type %s struct {\n", name)
	var fields []string
	for i, c := range names {
		field := goName(c)
		fields = append(fields, field)
		g.apart(i)
		t := g.typeOf(payloads[i], name+field)
		if !g.nilable(t) {
			t = "*" + t
		}
		fmt.Fprintf(&g.out, "\t%s %s `json:%q`\n", field, t, c+",omitzero")
	}
	if s.Fallback == "keep" {
		g.apart(len(names))
		g.out.WriteString("\t// Unrecognised is a case this build does not know, written back as it was read.\n")
		g.out.WriteString("\tUnrecognised JSONValue `json:\"-\"`\n")
	}
	g.out.WriteString("}\n")
	if s.Fallback == "keep" {
		none := make([]string, len(fields))
		for i, f := range fields {
			none[i] = "p." + f + " == nil"
		}
		fmt.Fprintf(&g.out, `
// MarshalJSON writes an unrecognised case back as it was read.
func (v %[1]s) MarshalJSON() ([]byte, error) {
	if v.Unrecognised != nil {
		return v.Unrecognised, nil
	}
	type plain %[1]s
	return json.Marshal(plain(v))
}

// UnmarshalJSON keeps a case this build does not know whole.
func (v *%[1]s) UnmarshalJSON(b []byte) error {
	type plain %[1]s
	var p plain
	if err := json.Unmarshal(b, &p); err != nil || (%[2]s) {
		*v = %[1]s{Unrecognised: append(JSONValue(nil), b...)}
		return nil
	}
	*v = %[1]s(p)
	return nil
}
`, name, strings.Join(none, " && "))
	}
}

// tagged writes objects told apart by a constant `type` as one struct with every
// variant's fields: the tag says which are there.
func (g *goGen) tagged(name string, s *Schema, tag string) {
	type merged struct {
		name     string
		schema   *Schema
		required int
		clash    bool
	}
	var order []string
	fields := map[string]*merged{}
	var tags []string
	for _, m := range s.AnyOf {
		for _, p := range m.Properties {
			if p.Name == tag {
				tags = append(tags, fmt.Sprintf("%q", p.Schema.Const))
				continue
			}
			f, ok := fields[p.Name]
			if !ok {
				f = &merged{name: p.Name, schema: p.Schema}
				fields[p.Name] = f
				order = append(order, p.Name)
			} else if tsType(f.schema) != tsType(p.Schema) {
				f.clash = true
			}
			if m.IsRequired(p.Name) {
				f.required++
			}
		}
	}
	fmt.Fprintf(&g.out, "type %s struct {\n", name)
	fmt.Fprintf(&g.out, "\t// %s is one of %s.\n", goName(tag), strings.Join(tags, ", "))
	fmt.Fprintf(&g.out, "\t%s string `json:%q`\n", goName(tag), tag)
	for _, n := range order {
		g.apart(1)
		f := fields[n]
		field := goName(n)
		t := "JSONValue"
		if !f.clash {
			t = g.field(name+field, f.schema, f.required == len(s.AnyOf))
		}
		jsonTag := n
		if f.required != len(s.AnyOf) {
			jsonTag += ",omitzero"
		}
		fmt.Fprintf(&g.out, "\t%s %s `json:%q`\n", field, t, jsonTag)
	}
	g.out.WriteString("}\n")
}

// inline names a type made for a schema written inside another, and queues it.
func (g *goGen) inline(hint string, s *Schema) string {
	name := hint
	for i := 2; g.named[name]; i++ {
		name = fmt.Sprintf("%s%d", hint, i)
	}
	g.named[name] = true
	g.queue = append(g.queue, func() { g.definition(name, s) })
	return name
}

// typeOf is the Go type for a schema; hint names any type it has to make.
func (g *goGen) typeOf(s *Schema, hint string) string {
	switch {
	case s.Ref != "":
		name := s.RefName()
		if t := g.doc.Definitions[name].GoType; t != "" {
			return t
		}
		return name
	case s.AnyOf != nil:
		if inner, ok := s.Nullable(); ok {
			t := g.typeOf(inner, hint)
			if g.nilable(t) {
				return t
			}
			return "*" + t
		}
		if _, _, ok := s.Cases(); ok {
			return g.inline(hint, s)
		}
		if _, ok := s.Tagged(); ok {
			return g.inline(hint, s)
		}
		if s.Strings() {
			return "string"
		}
		return "JSONValue"
	case s.HasConst || s.Enum != nil:
		if s.Is("string") || s.Types == nil {
			return "string"
		}
	case len(s.Types) > 1:
		if inner, ok := s.Nullable(); ok {
			return "*" + g.typeOf(inner, hint)
		}
		return "JSONValue"
	}
	switch {
	case s.Is("string"):
		return "string"
	case s.Is("integer"):
		return "int64"
	case s.Is("number"):
		return "float64"
	case s.Is("boolean"):
		return "bool"
	case s.Is("array"):
		if s.Items == nil {
			return "[]JSONValue"
		}
		item := g.typeOf(s.Items, hint+"Item")
		if s.MinItems != nil && s.MaxItems != nil && *s.MinItems == *s.MaxItems && *s.MinItems > 0 {
			return fmt.Sprintf("[%d]%s", *s.MinItems, item)
		}
		return "[]" + item
	case s.Is("object"):
		if len(s.Properties) > 0 {
			return g.inline(hint, s)
		}
		if s.More != nil && s.More.Not != nil {
			return "struct{}"
		}
		if s.More != nil {
			return "map[string]" + g.typeOf(s.More, hint+"Value")
		}
		return "struct{}"
	}
	return "JSONValue"
}

var initialisms = map[string]string{"id": "ID", "url": "URL", "uri": "URI", "mcp": "MCP", "acp": "ACP", "html": "HTML", "json": "JSON", "ssh": "SSH", "cli": "CLI"}

// goName is an exported Go name for a JSON name: `_0` is Value, `agentID` is AgentID,
// `request_archive` and `mcp/health/check` are RequestArchive and MCPHealthCheck.
func goName(s string) string {
	if s == "_0" {
		return "Value"
	}
	var b strings.Builder
	for _, word := range strings.FieldsFunc(s, func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) }) {
		if up, ok := initialisms[word]; ok {
			b.WriteString(up)
			continue
		}
		r := []rune(word)
		r[0] = unicode.ToUpper(r[0])
		b.WriteString(string(r))
	}
	if b.Len() == 0 || unicode.IsDigit([]rune(b.String())[0]) {
		return "V" + b.String()
	}
	return b.String()
}

// goMethods makes the method table: a typed name for each method and notification, and
// the failure codes.
func goMethods(doc *Document, rpcs []*RPC) (string, error) {
	g := &goGen{doc: doc, named: map[string]bool{}}
	for _, name := range doc.Names {
		g.named[name] = true
	}
	var body strings.Builder
	for _, rpc := range rpcs {
		// One declaration each, not a block that gofmt aligns (#2020).
		fmt.Fprintf(&body, "\n// What %s answers (%s.openrpc.json).\n", map[string]string{"host": "a host", "control": "the control plane"}[rpc.Target],
			map[string]string{"host": "daemon", "control": "control"}[rpc.Target])
		for _, m := range rpc.Methods {
			name := goName(m.Name)
			params := g.typeOf(m.Params, name+"Params")
			if m.Notification {
				fmt.Fprintf(&body, "var Notify%s = Notification[%s]{%q}\n", name, params, m.Name)
			} else {
				fmt.Fprintf(&body, "var Call%s = Method[%s, %s]{%q}\n", name, params, g.typeOf(m.Result, name+"Result"), m.Name)
			}
		}
		if len(rpc.Errors) > 0 {
			body.WriteString("\n// The codes a call can fail with (DaemonAPI.Failure).\n")
			for _, e := range rpc.Errors {
				fmt.Fprintf(&body, "const Failure%s = %d\n", goName(e.Name), e.Code)
			}
		}
	}
	g.out.WriteString(body.String())
	for len(g.queue) > 0 {
		next := g.queue[0]
		g.queue = g.queue[1:]
		next()
	}
	return gofmt(file(g.out.String()))
}
